_raw = array('h'); _raw.frombytes(zlib.decompress(base64.b64decode(''.join(_BLOB.split()))))
import sys as _sys
if _sys.byteorder != 'little':
    _raw.byteswap()
DX = [_raw[i] * Q for i in range(NU * NV)]                 # (row-major: v rows of u)
DY = [_raw[NU * NV + i] * Q for i in range(NU * NV)]
del _raw
SU, SV = (NU - 1) / (U1 - U0), (NV - 1) / (V1 - V0)

def imp(u, v):
    """the map's imperfections at one point (plain Python): (dx, dy), units"""
    fu = min(max((u - U0) * SU, 0.0), NU - 1.000001); fv = min(max((v - V0) * SV, 0.0), NV - 1.000001)
    i, j = int(fu), int(fv); a, b = fu - i, fv - j
    k = j * NU + i
    dx = (DX[k] * (1 - a) + DX[k + 1] * a) * (1 - b) + (DX[k + NU] * (1 - a) + DX[k + NU + 1] * a) * b
    dy = (DY[k] * (1 - a) + DY[k + 1] * a) * (1 - b) + (DY[k + NU] * (1 - a) + DY[k + NU + 1] * a) * b
    return dx, dy

_npt = None
def imp_np(np, u, v):
    """the same for numpy arrays"""
    global _npt
    if _npt is None:
        _npt = (np.array(DX, np.float64).reshape(NV, NU), np.array(DY, np.float64).reshape(NV, NU))
    TX, TY = _npt
    fu = np.clip((u - U0) * SU, 0.0, NU - 1.000001); fv = np.clip((v - V0) * SV, 0.0, NV - 1.000001)
    i = fu.astype(np.intp); j = fv.astype(np.intp); a = fu - i; b = fv - j
    def bl(T):
        return (T[j, i] * (1 - a) + T[j, i + 1] * a) * (1 - b) + (T[j + 1, i] * (1 - a) + T[j + 1, i + 1] * a) * b
    return bl(TX), bl(TY)
